#include <stdio.h>
#include <string.h>
#include <thinkthen.h>

thinkthen_engine *tt = thinkthen_engine_new();

/* three messages name one team each: billing, shipping,
   and account. The fourth names a parcel and a login, so
   no team reaches 0.9 and its answer is null */
const char *texts[] = {"Please refund the extra fee on my invoice.",
    "My parcel went to the wrong address.",
    "I cannot reset my password.",
    "My parcel never came, and now I cannot log in to track it."};
char choose[320];
for (int i = 0; i < 4; i++) {
    snprintf(choose, sizeof choose,
        "{\"choose\": \"Which team owns this?\", "
        "\"options\": [\"billing\", \"shipping\", \"account\"], "
        "\"threshold\": 0.9, \"evidence\": \"%s\"}", texts[i]);
    char *out = thinkthen_call(tt, choose);
    puts(out ? out : thinkthen_error_message(tt));
    thinkthen_free_string(out);
}
